import json,sys
from pathlib import Path
public, denied=json.loads(sys.argv[1])
result={"public_read":False,"denied":[]}
try:
 Path(public).read_bytes(); result["public_read"]=True
except OSError as e: result["public_error"]=type(e).__name__
for name in denied:
 try:
  Path(name).read_bytes(); result["denied"].append({"path":name,"result":"READABLE"})
 except OSError as e: result["denied"].append({"path":name,"result":type(e).__name__})
print(json.dumps(result))
sys.exit(0 if result["public_read"] and all(x["result"]=="PermissionError" for x in result["denied"]) else 1)

